def check_kawaii(A):
    N = len(A)
    if N == 0:
        return False

    M = max(A)

    # Check condition 1: If k appears, k-1 appears.
    # Since M = max(A), we only need to check k from 2 to M.
    # This is implicitly guaranteed if we ensure all numbers 1..M are present in the sequence.

    # Check presence of 1 to M
    present = set(A)
    if M not in present:
        return False # Should not happen if M is defined correctly, but safety check
    if 1 not in present:
        return False
    for k in range(2, M + 1):
        if k in present and (k-1) not in present:
            return False

    # Check condition 2: L_{k-1} < R_k for k >= 2
    for k in range(2, M + 1):
        if k not in present:
            continue

        k_minus_1 = k - 1

        # Find L_{k-1} (First occurrence of k-1)
        try:
            L_k_minus_1 = A.index(k_minus_1)
        except ValueError:
            # Should not happen if presence check passed, but handle defensively
            continue 

        # Find R_k (Last occurrence of k)
        R_k = -1
        for i in range(N - 1, -1, -1):
            if A[i] == k:
                R_k = i
                break

        if R_k == -1:
            # k is not present, skip check
            continue

        if L_k_minus_1 >= R_k:
            return False

    return True

def count_kawaii_sequences(N, M):
    """Counts kawaii sequences of length N using elements up to M, provided M must appear."""

    # Generate all sequences of length N using alphabet {1, ..., M}
    from itertools import product
    count = 0

    # Iterating over all M^N sequences
    for seq_tuple in product(range(1, M + 1), repeat=N):
        A = list(seq_tuple)

        # Optimization: Only check sequences that actually contain M.
        if M not in A:
            continue

        if check_kawaii(A):
            count += 1

    return count

